 ```json
{
  "function_name": "merge_asof",
  "description": "Performs an 'as-of' merge, similar to a left join but with the right DataFrame sorted on the key. This allows for matching rows in the right DataFrame that are 'closest' (in the specified direction) to each row in the left DataFrame.",
  "parameters": {
    "left": {
      "type": "DataFrame",
      "description": "The left DataFrame to merge."
    },
    "right": {
      "type": "DataFrame",
      "description": "The right DataFrame to merge with. It should be sorted by the key(s)."
    },
    "on": {
      "type": "str or list of str, optional",
      "description": "Column or index level names to join on in 'right'. Must also be in 'left'. If not specified, both DataFrames must have exactly one index level and these levels must have the same name."
    },
    "left_on": {
      "type": "str or list of str, optional",
      "description": "Column or index level names to join on in 'left'. Must also be in 'right'. If not specified, it defaults to `on`."
    },
    "right_on": {
      "type": "str or list of str, optional",
      "description": "Column or index level names to join on in 'right'. Must also be in 'left'. If not specified, it defaults to `on`."
    },
    "left_index": {
      "type": "bool, default False",
      "description": "If True, use the index of 'left' as the merge key(s)."
    },
    "right_index": {
      "type": "bool, default False",
      "description": "If True, use the index of 'right' as the merge key(s)."
    },
    "by": {
      "type": "str or list of str, optional",
      "description": "Column or index level names to group by before doing an asof join. This is similar to a left join after grouping each DataFrame by the specified keys."
    },
    "left_by": {
      "type": "str or list of str, optional",
      "description": "Column or index level names to group by on 'left' before doing an asof join. Similar to `by` but for the left DataFrame."
    },
    "right_by": {
      "type": "str or list of str, optional",
      "description": "Column or index level names to group by on 'right' before doing an asof join. Similar to `by` but for the right DataFrame."
    },
    "suffixes": {
      "type": "tuple of str, default ('_x', '_y')",
      "description": "Suffixes to add to overlapping column names in left and right DataFrame respectively."
    },
    "tolerance": {
      "type": "Timedelta or float, optional",
      "description": "Maximum time difference for each merge pair. Must be specified as a timedelta if joining on a datetimelike column."
    },
    "allow_exact_matches": {
      "type": "bool, default True",
      "description": "If True, allow exact matches on the tolerance boundary to fall back on prior data (in the 'left' direction) or subsequent data (in the 'right' direction)."
    },
    "direction": {
      "type": "str, default 'backward'",
      "description": "Direction of search to find the nearest match. Options are 'backward', 'forward', and 'nearest'."
    }
  },
  "return_value": {
    "type": "DataFrame",
    "description": "The result of the asof merge."
  }
}
```

